<?php
declare(strict_types=1);namespace App\Controllers;
use App\Core\Request;use App\Core\Database;use App\Models\AuthModel;
final class AuthController extends BaseController {public function show(Request $r):void{if(current_user())redirect('/');$this->view('auth/login',['error'=>flash('error')]);}public function login(Request $r):void{$this->csrf();$email=filter_var(trim((string)$r->input('email')),FILTER_VALIDATE_EMAIL);$password=(string)$r->input('password');$model=new AuthModel();$u=$email?$model->byEmail($email):null;if(!$u||!password_verify($password,$u['password_hash'])){flash('error','Invalid email or password.');redirect('/login');}session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['full_name'],'email'=>$u['email']];$_SESSION['permissions']=$model->permissions((int)$u['id']);$_SESSION['roles']=$model->roles((int)$u['id']);Database::connection()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);\audit_log('login','users',(int)$u['id']);redirect('/');}public function logout(Request $r):void{$this->csrf();$_SESSION=[];session_regenerate_id(true);redirect('/login');}}
